import numpy as np


def validate_pool_params(
    h: int,
    w: int,
    kernel_size: int,
    stride: int,
    mode: str,
) -> tuple[int, int]:
    """Pooling প্যারামিটার যাচাই করে আউটপুট (H_out, W_out) রিটার্ন করে।"""
    if mode not in ("max", "avg"):
        raise ValueError(f"mode must be 'max' or 'avg', got {mode!r}.")
    if kernel_size < 1 or stride < 1:
        raise ValueError("kernel_size and stride must be >= 1.")
    if kernel_size > h or kernel_size > w:
        raise ValueError(
            f"kernel_size={kernel_size} cannot exceed input shape ({h}, {w})."
        )
    h_out = (h - kernel_size) // stride + 1
    w_out = (w - kernel_size) // stride + 1
    return h_out, w_out


def pool2d(
    x: np.ndarray,
    kernel_size: int,
    stride: int | None = None,
    mode: str = "max",
) -> np.ndarray:
    """Apply 2D Max or Average Pooling over a 2D feature map (H, W).

    Args:
        x: 2D array of shape (H, W).
        kernel_size: Square pooling window size k (>= 1).
        stride: Step size s. Defaults to kernel_size when None.
        mode: Either 'max' or 'avg'.

    Returns:
        Pooled 2D float64 array of shape (H_out, W_out).
    """
