class SpatialPool2D:
    """Channel-wise 2D Pooling & Global Average Pooling module for (C, H, W) tensors."""

    def __init__(
        self,
        kernel_size: int = 2,
        stride: int | None = None,
        mode: str = "max",
    ) -> None:
        self.kernel_size = kernel_size
        self.stride = stride
        self.mode = mode

    def forward(self, x: np.ndarray) -> np.ndarray:
        x_arr = np.asarray(x, dtype=np.float64)
        if x_arr.ndim != 3:
            raise ValueError("SpatialPool2D expects a 3D tensor (C, H, W).")
        pooled = [
            pool2d(x_arr[c], self.kernel_size, self.stride, self.mode)
            for c in range(x_arr.shape[0])
        ]
        return np.stack(pooled, axis=0)

    @staticmethod
    def global_avg_pool(x: np.ndarray) -> np.ndarray:
        """Collapses (C, H, W) spatial dims into a (C,) descriptor for classifier heads."""
        x_arr = np.asarray(x, dtype=np.float64)
        if x_arr.ndim != 3:
            raise ValueError("global_avg_pool expects a 3D tensor (C, H, W).")
        return np.mean(x_arr, axis=(1, 2))
